const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md config/zellij/layouts/code.kdl home/codex.nix config/claude/settings.json","max_output_tokens":7500}),
  tools.exec_command({cmd:"sed -n '1,260p' config/zellij/config.kdl","max_output_tokens":6500}),
  tools.exec_command({cmd:"git diff -- config/zellij/config.kdl config/zellij/layouts/code.kdl home/home.nix home/agent.nix scripts/command-palette.sh scripts/session-picker.sh","max_output_tokens":9000}),
  tools.exec_command({cmd:"rg -n 'codex.nix|claude-statusline|layout|status.?line|status.?bar' home scripts README* config .codex .agents","max_output_tokens":6000})
]); results.forEach((r,i)=>text({index:i,...r}));

