readlink -f result/bin/zellij   # must NOT point at a zellij-unwrapped-X.Y.Z store path
```

nixpkgs' `postInstall` also runs `mandown docs/MANPAGE.md`, which upstream
deleted in zellij-org/zellij#5426, so the flake overrides `postInstall` to
install only the shell completions.

### Rebasing the fork

```bash
git clone https://github.com/tteggel/zellij /tmp/zellij-fork
cd /tmp/zellij-fork
git remote add upstream https://github.com/zellij-org/zellij.git
git fetch upstream main
git checkout -b pane-shaders-static-next upstream/main
git cherry-pick pane-shaders-static
# resolve conflicts, especially in output/mod.rs and grid.rs
git push origin pane-shaders-static-next
# update flake locks as above
# once happy: rename pane-shaders-static-next → pane-shaders-static via gh
```

Push uses SSH (`git@github.com:tteggel/zellij.git`) because rebasing usually pulls in upstream `.github/workflows/*.yml` changes that the OAuth token can't authorize.

Verify before pushing by building straight from the local checkout — no push, no
lock churn:

```bash
nix build ./bespoke/zellij/dim-unfocused#zellij \
  --override-input zellij-src "git+file:///path/to/zellij-fork?ref=pane-shaders-static-next"
```

**Proto tag numbers are the recurring conflict.** The patch claims one
`CommandName` and one `PluginCommand.payload` tag, and upstream keeps taking the
next free values. On each rebase, renumber ours above whatever upstream now
occupies, in both `plugin_command.proto` and the generated
`assets/prost/api.plugin_command.rs` (enum value, `as_str_name`, `from_str_name`,
and the `tags="…"` list on `PluginCommand::payload`). History so far:
215→227→229→233 for `CommandName`, 164→172→176 for the payload oneof.

Upstream also raises its MSRV regularly (0.45 needs rustc 1.95), so a rebase
usually means bumping the sub-flake's `nixpkgs` and `rust-overlay` too.
{
  description = "Zellij (from fork with pane shader support) + dim-unfocused plugin";

  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable";
    rust-overlay = {
      url = "github:oxalica/rust-overlay";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    zellij-src = {
      url = "github:tteggel/zellij/pane-shaders-static";
      flake = false;
    };
  };

  outputs = {
    self,
    nixpkgs,
    rust-overlay,
    zellij-src,
  }: let
    system = "x86_64-linux";
    pkgs = import nixpkgs {
      inherit system;
      overlays = [(import rust-overlay)];
    };
    rustToolchain = pkgs.rust-bin.stable.latest.default.override {
      targets = ["wasm32-wasip1" "wasm32-unknown-unknown"];
    };
    pluginCargoVendored = pkgs.rustPlatform.importCargoLock {
      lockFile = ./Cargo.lock;
    };
    zellijCargoVendored = pkgs.rustPlatform.importCargoLock {
      lockFile = zellij-src + "/Cargo.lock";
    };
    shaderWasm = pkgs.stdenv.mkDerivation {
      pname = "dim-shader";
      version = "0.1.0";
      src = ./shader;
      nativeBuildInputs = [rustToolchain];
      buildPhase = ''
        export HOME=$TMPDIR
        mkdir -p .cargo
        cat > .cargo/config.toml <<'TOML'
        [source.crates-io]
        replace-with = "vendored-sources"

        [source.vendored-sources]
        directory = "vendor"
        TOML

        cargo build --target wasm32-unknown-unknown --release --offline 2>/dev/null || \
        cargo build --target wasm32-unknown-unknown --release
      '';
      installPhase = ''
        mkdir -p $out
        cp target/wasm32-unknown-unknown/release/dim_shader.wasm $out/
      '';
    };
  in {
    packages.${system} = rec {
      # Override zellij-unwrapped, not zellij: nixpkgs' `zellij` is only a
      # symlinkJoin wrapper, so overriding it leaves the stock binary in place.
      zellij = pkgs.zellij-unwrapped.overrideAttrs (old: {
        pname = "zellij";
        version = "0.46.0-unstable";
        src = zellij-src;
        cargoDeps = zellijCargoVendored;
        postPatch = ''
          substituteInPlace Cargo.toml \
            --replace-fail ', "vendored_curl"' "" || true
        '';
        # Upstream removed docs/MANPAGE.md (zellij-org/zellij#5426), so drop
        # nixpkgs' mandown step and keep only the shell completions.
        postInstall = ''
          installShellCompletion --cmd zellij \
            --bash <($out/bin/zellij setup --generate-completion bash) \
            --fish <($out/bin/zellij setup --generate-completion fish) \
            --zsh <($out/bin/zellij setup --generate-completion zsh)
        '';
        doInstallCheck = false;
      });

      dim-unfocused = pkgs.stdenv.mkDerivation {
        pname = "dim-unfocused";
        version = "0.1.0";
        src = builtins.path {
          path = ./.;
          filter = path: type:
            let name = builtins.baseNameOf path;
            in name != "flake.nix" && name != "flake.lock" && name != "target" && name != "zellij-src" && name != "result" && name != "shader";
        };

        nativeBuildInputs = [rustToolchain];

        buildPhase = ''
          export HOME=$TMPDIR
          ln -s ${zellij-src} zellij-src
          ln -s ${pluginCargoVendored} vendor
          mkdir -p .cargo
          cat > .cargo/config.toml <<'TOML'
          [source.crates-io]
          replace-with = "vendored-sources"

          [source.vendored-sources]
          directory = "vendor"
          TOML

          export SHADER_WASM_PATH="${shaderWasm}/dim_shader.wasm"
          cargo build --target wasm32-wasip1 --release --offline
        '';

        installPhase = ''
          mkdir -p $out/share/zellij/plugins
          cp target/wasm32-wasip1/release/dim-unfocused.wasm $out/share/zellij/plugins/
        '';
      };
      default = dim-unfocused;
    };

    devShells.${system}.default = pkgs.mkShell {
      buildInputs = [rustToolchain];
    };
  };
}

